// Compiled only against the private ORB copy generated by build.py.
#include "System.h"
#include "KeyFrame.h"
#include "Tracking.h"
#include <nlohmann/json.hpp>

namespace ORB_SLAM3 {
std::string System::LiveVioSnapshot(double timestamp) {
    using nlohmann::json;
    const auto s = mpTracker->GetLiveVioState();
    const bool valid = s.valid && s.timestamp == timestamp;
    // Early exits in Track may have reset the map. Read its current identity,
    // but never combine a valid pose with state from a different snapshot.
    const auto identity = valid ? s.identity : GetPublicationIdentity();
    json out = {{"valid", valid}, {"state", valid ? s.tracking_state : GetTrackingState()},
        {"imu_initialized", s.imu_initialized},
        {"initialization_complete", s.initialization_complete},
        {"map_id", std::to_string(identity.first)+"_"+std::to_string(identity.second)},
        {"revision", s.revision}, {"T_world_camera", nullptr}};
    if (valid) {
        const auto pose = s.camera_from_world.inverse().matrix();
        json rows = json::array();
        for (int r=0;r<4;++r) { json row=json::array(); for(int c=0;c<4;++c) row.push_back(pose(r,c)); rows.push_back(row); }
        out["T_world_camera"] = rows;
    }
    return out.dump();
}

std::string System::ReconstructionSnapshot() {
    using nlohmann::json;
    json out = {{"version", 2}, {"state", GetTrackingState()}, {"maps", json::array()}};
    auto active = mpAtlas->GetCurrentMap()->GetPublicationIdentity();
    out["active_map"] = std::to_string(active.first) + "_" + std::to_string(active.second);
    // Atlas retains map objects until a tracking-thread reset. This method is
    // called only on that same tracking thread. Copy each map under its update
    // lock; do not expose pointers or hold multiple map locks during merges.
    for (auto* map : mpAtlas->GetAllMaps()) {
        std::unique_lock<std::mutex> lock(map->mMutexMapUpdate);
        auto identity = map->GetPublicationIdentity();
        json entry = {{"id", std::to_string(identity.first) + "_" + std::to_string(identity.second)},
                      {"imu_initialized", map->isImuInitialized()},
                      {"imu_initialization_complete", map->mReconstructionImuReady.load()},
                      {"revision", map->GetMapChangeIndex()}, {"keyframes", json::array()}};
        for (auto* kf : map->GetAllKeyFrames()) {
            if (kf->isBad() || kf->GetMap() != map) continue;
            const auto pose = kf->GetPoseInverse().matrix();
            if (!pose.allFinite()) continue;
            json matrix = json::array();
            for (int r = 0; r < 4; ++r) {
                json row = json::array();
                for (int c = 0; c < 4; ++c) row.push_back(pose(r,c));
                matrix.push_back(row);
            }
            entry["keyframes"].push_back({{"id", kf->mnId}, {"timestamp", kf->mTimeStamp},
                {"image_key", std::to_string(llround(kf->mTimeStamp * 1e6))}, {"T_world_camera", matrix}});
        }
        out["maps"].push_back(entry);
    }
    return out.dump();
}

void System::FinishReconstruction() {
    // The fork's Shutdown() calls an unsafe profiling dump before joining the
    // mapper. A reset also leaves unequal profiling-vector lengths. Request
    // finish directly and join before reading the final geometry instead.
    {
        std::unique_lock<std::mutex> lock(mMutexReset);
        mbShutDown = true;
    }
    mpLocalMapper->RequestFinish();
    mpLoopCloser->RequestFinish();
    if (mptLocalMapping && mptLocalMapping->joinable()) mptLocalMapping->join();
    if (mptLoopClosing && mptLoopClosing->joinable()) mptLoopClosing->join();
    while (mpLoopCloser->isRunningGBA()) usleep(10000);
}
}
